mapper.select:
SELECT COUNT(1)
FROM sys_role
WHERE tenant_id = #{tenantId}
  AND role_key = #{roleKey}
  AND del_flag = 0

mapper.insert:
INSERT INTO sys_role_resource (tenant_id, role_id, resource_id, create_time)
SELECT #{targetTenantId}, #{targetRoleId}, rr.resource_id, CURRENT_TIMESTAMP
FROM sys_role_resource rr
WHERE rr.tenant_id = #{sourceTenantId}
  AND rr.role_id = #{sourceRoleId}
  AND rr.resource_id NOT IN (
      SELECT r.id
      FROM sys_resource r
      WHERE r.del_flag = 0
        AND (
            r.path LIKE '/system/tenant%'
            OR r.perms LIKE 'system:tenant%'
            OR r.resource_name = '租户管理'
        )
  )
  AND NOT EXISTS (
      SELECT 1
      FROM sys_role_resource x
      WHERE x.tenant_id = #{targetTenantId}
        AND x.role_id = #{targetRoleId}
        AND x.resource_id = rr.resource_id
  )
